import subprocess, json, sys

def run(req):
    p = subprocess.run([sys.executable, "main.py"], input=json.dumps(req), capture_output=True, text=True, check=True)
    return json.loads(p.stdout)

# Protocol 1: same delivery_id across accounts is same identity; earliest instant wins; offset crosses date boundary.
req = {"command":"accepted","protocol":"1","receipts":[
  {"record_id":"R-2","account_id":"A","delivery_id":"D-1","occurred_at":"2026-04-01T10:00:00Z","payload":"p2"},
  {"record_id":"R-1","account_id":"B","delivery_id":"D-1","occurred_at":"2026-04-01T09:00:00+02:00","payload":"p1"}
]}
print("protocol1 offset boundary:", run(req))

# Tie on instant -> smallest record_id wins, protocol 2 latest-instant semantics with tie.
req2 = {"command":"accepted","protocol":"2","receipts":[
  {"record_id":"R-9","account_id":"A","delivery_id":"D-1","occurred_at":"2026-04-01T10:00:00Z","payload":"p9"},
  {"record_id":"R-3","account_id":"A","delivery_id":"D-1","occurred_at":"2026-04-01T10:00:00+00:00","payload":"p3"},
  {"record_id":"R-5","account_id":"A","delivery_id":"D-1","occurred_at":"2026-04-01T05:00:00Z","payload":"p5"}
]}
print("protocol2 tie same instant:", run(req2))

# Default protocol (omitted) should behave like protocol 2 (current).
req3 = {"command":"accepted","receipts":[
  {"record_id":"R-1","account_id":"A","delivery_id":"D-1","occurred_at":"2026-04-01T10:00:00Z","payload":"p1"},
  {"record_id":"R-2","account_id":"B","delivery_id":"D-1","occurred_at":"2026-04-01T11:00:00Z","payload":"p2"}
]}
print("default protocol:", run(req3))

# summary/count for same request should match accepted/duplicate counts
req4 = {"command":"summary","receipts":req2["receipts"]}
print("summary matching:", run(req4))

